input.command:
chcp 65001 | Out-Null; @(
  @{n='cursor';p="$env:USERPROFILE\.cursor\skills"},
  @{n='claude';p="$env:USERPROFILE\.claude\skills"},
  @{n='codex';p="$env:USERPROFILE\.codex\skills"},
  @{n='agents';p="$env:USERPROFILE\.agents\skills"}
) | ForEach-Object {
  $c = if (Test-Path $_.p) { (Get-ChildItem $_.p -Directory | Where-Object { Test-Path (Join-Path $_.FullName 'SKILL.md') }).Count } else { 0 }
  "$($_.n)=$c ($($_.p))"
}
# Desktop projects with AGENTS.md
Get-ChildItem "$env:USERPROFILE\Desktop" -Directory -EA SilentlyContinue | ForEach-Object {
  $has = @()
  if (Test-Path (Join-Path $_.FullName 'AGENTS.md')) { $has += 'AGENTS' }
  if (Test-Path (Join-Path $_.FullName '.github\agent')) { $has += 'agent-mem' }
  if ($has.Count -gt 0) { "$($_.Name): $($has -join ',')" }
}

