input.command:
chcp 65001 | Out-Null; [Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $OutputEncoding = [System.Text.Encoding]::UTF8
$homes = @(
  "$env:USERPROFILE\.cursor",
  "$env:USERPROFILE\.claude",
  "$env:USERPROFILE\.codex",
  "$env:USERPROFILE\.ai-workspace",
  "$env:USERPROFILE\.agents",
  "$env:USERPROFILE\.cc-switch",
  "$env:APPDATA\Cursor",
  "$env:APPDATA\Claude",
  "$env:USERPROFILE\Desktop\全局配置"
)
foreach ($p in $homes) {
  if (Test-Path $p) {
    $size = (Get-ChildItem $p -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum / 1MB
    Write-Host ("{0:N1} MB  {1}" -f $size, $p)
  } else { Write-Host "MISSING  $p" }
}
Write-Host "---全局配置 dirs---"
Get-ChildItem "$env:USERPROFILE\Desktop\全局配置" -Force -Directory | ForEach-Object {
  $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum / 1MB
  "{0:N1} MB  {1}" -f $s, $_.Name
}
